import 'package:flutter/material.dart';
import 'package:projet_tuto/presentation/screens/home_screen.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:projet_tuto/firebase_options.dart';
import 'package:projet_tuto/routes.dart';


Future<void> main() async {
  // Required before any async call made ahead of runApp:
  // native plugins (Firebase) need the Flutter engine to be ready.
  WidgetsFlutterBinding.ensureInitialized();
  // Starts Firebase once, with the config generated by flutterfire
  // (currentPlatform picks the Android or web one).
  await Firebase.initializeApp(
    options: DefaultFirebaseOptions.currentPlatform,
  );

  runApp(
    MaterialApp(            // ⚠️ plus de "const" : ThemeData n'est pas constant
      title: 'My app',
      theme: ThemeData(
        // Pour les widgets Icon "simples"
        iconTheme: const IconThemeData(
          color: Colors.green,
          size: 28,
        ),
        // Pour les IconButton
        iconButtonTheme: IconButtonThemeData(
          style: IconButton.styleFrom(
            foregroundColor: Colors.green,          // icône quand le bouton est actif
            disabledForegroundColor: Colors.green,  // icône quand onPressed: null
            iconSize: 28,
          ),
        ),
      ),
      initialRoute: AppRoutes.welcome,
      routes: AppRoutes.routes,
    ),
  );
}
